#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/fuel_gauge.h>
#include <zephyr/logging/log.h>
#include <zephyr/pm/device.h>
#include <zephyr/sys/byteorder.h> /* For sys_byte_reverse_u8 in crc8 */
#include <zephyr/sys/crc.h>       /* Declares crc8, but we define it here */

LOG_MODULE_REGISTER(lc709203f, CONFIG_FUEL_GAUGE_LOG_LEVEL);

/*
 * Workaround for undefined reference to `crc8`.
 * This function is typically provided by Zephyr's lib/utils/crc.c
 * when CONFIG_CRC is enabled. Since it's not linked, we provide a local
 * implementation matching the Zephyr API. This function must not be static
 * to resolve the global undefined reference.
 */
uint8_t crc8(const uint8_t *src, size_t len, uint8_t crc_poly,
             uint8_t initial_value, bool reflect_data, uint8_t final_xor)
{
    uint8_t crc = initial_value;
    size_t i, j;

    for (i = 0; i < len; i++) {
        uint8_t byte = src[i];

        if (reflect_data) {
            byte = sys_byte_reverse_u8(byte);
        }

        crc ^= byte;

        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc_poly;
            } else {
                crc <<= 1;
            }            
        }
    }

    if (reflect_data) {
        crc = sys_byte_reverse_u8(crc);
    }

    return crc ^ final_xor;
}

/* LC709203F registers */
#define LC709203F_REG_IC_VERSION        0x11
#define LC709203F_REG_CELL_VOLTAGE      0x02
#define LC709203F_REG_APA               0x0A
#define LC709203F_REG_ITE               0x04
#define LC709203F_REG_CELL_TEMP         0x08
#define LC709203F_REG_THERMISTOR_B      0x06
#define LC709203F_REG_ALARM_WARNING     0x01
#define LC709203F_REG_STATUS            0x00
#define LC709203F_REG_RSOC              0x0D
#define LC709203F_REG_CHANGE_PARAM      0x12
#define LC709203F_REG_PROFILE           0x13
#define LC709203F_REG_CC_MODE           0x14
#define LC709203F_REG_ALARM_THRESHOLD   0x15
#define LC709203F_REG_TEMP_MODE         0x16
#define LC709203F_REG_VCELL_MODE        0x17

/* LC709203F commands */
#define LC709203F_CMD_GET_IC_VERSION    0x0001
#define LC709203F_CMD_SET_APA           0x0001
#define LC709203F_CMD_SET_ITE           0x0001
#define LC709203F_CMD_SET_THERMISTOR_B  0x0001
#define LC709203F_CMD_SET_PROFILE       0x0001
#define LC709203F_CMD_SET_CC_MODE       0x0001
#define LC709203F_CMD_SET_ALARM_THRESHOLD 0x0001
#define LC709203F_CMD_SET_TEMP_MODE     0x0001
#define LC709203F_CMD_SET_VCELL_MODE    0x0001

/* LC709203F constants */
#define LC709203F_I2C_ADDRESS           0x0B
#define LC709203F_CRC_POLYNOMIAL        0x07
#define LC709203F_CRC_INITIAL_VALUE     0x00
#define LC709203F_CRC_FINAL_XOR         0x00

struct lc709203f_config {
    struct i2c_dt_spec i2c;
};

struct lc709203f_data {
    uint16_t rsoc;
    uint16_t cell_voltage;
    uint16_t cell_temp;
    uint16_t apa;
    uint16_t ite;
    uint16_t thermistor_b;
    uint16_t alarm_warning;
    uint16_t status;
    uint16_t profile;
    uint16_t cc_mode;
    uint16_t alarm_threshold;
    uint16_t temp_mode;
    uint16_t vcell_mode;
    struct k_mutex mutex;
};

static int lc709203f_read_word(const struct device *dev, uint8_t reg_addr, uint16_t *value)
{
    const struct lc709203f_config *config = dev->config;
    uint8_t buf[4]; /* Command, Data_L, Data_H, CRC */
    int ret;

    buf[0] = reg_addr;
    buf[1] = 0x00; /* Dummy data for read command */
    buf[2] = 0x00; /* Dummy data for read command */
    buf[3] = crc8(buf, 3, LC709203F_CRC_POLYNOMIAL, LC709203F_CRC_INITIAL_VALUE,
                  false, LC709203F_CRC_FINAL_XOR);

    ret = i2c_write_read_dt(&config->i2c, buf, 1, buf, 3);
    if (ret < 0) {
        LOG_ERR("I2C read failed: %d", ret);
        return ret;
    }

    uint8_t received_crc = buf[2];
    uint8_t calculated_crc = crc8(buf, 2, LC709203F_CRC_POLYNOMIAL,
                                  LC709203F_CRC_INITIAL_VALUE, false, LC709203F_CRC_FINAL_XOR);

    if (received_crc != calculated_crc) {
        LOG_ERR("CRC mismatch: received 0x%02x, calculated 0x%02x",
                received_crc, calculated_crc);
        return -EIO;
    }

    *value = sys_le16_to_cpu(UNALIGNED_GET((uint16_t *)&buf[0]));

    return 0;
}

static int lc709203f_write_word(const struct device *dev, uint8_t reg_addr, uint16_t value)
{
    const struct lc709203f_config *config = dev->config;
    uint8_t buf[4]; /* Command, Data_L, Data_H, CRC */
    int ret;

    buf[0] = reg_addr;
    UNALIGNED_PUT(sys_cpu_to_le16(value), (uint16_t *)&buf[1]);
    buf[3] = crc8(buf, 3, LC709203F_CRC_POLYNOMIAL, LC709203F_CRC_INITIAL_VALUE,
                  false, LC709203F_CRC_FINAL_XOR);

    ret = i2c_write_dt(&config->i2c, buf, sizeof(buf));
    if (ret < 0) {
        LOG_ERR("I2C write failed: %d", ret);
        return ret;
    }

    return 0;
}

static int lc709203f_get_prop(const struct device *dev,
                              enum fuel_gauge_property prop,
                              union fuel_gauge_propval *val)
{
    struct lc709203f_data *data = dev->data;
    int ret;

    k_mutex_lock(&data->mutex, K_FOREVER);

    switch (prop) {
    case FUEL_GAUGE_RSOC:
        ret = lc709203f_read_word(dev, LC709203F_REG_RSOC, &data->rsoc);
        if (ret == 0) {
            val->rsoc = data->rsoc / 100; /* RSOC is in 0.01% units */
        }
        break;
    case FUEL_GAUGE_VOLTAGE:
        ret = lc709203f_read_word(dev, LC709203F_REG_CELL_VOLTAGE, &data->cell_voltage);
        if (ret == 0) {
            val->voltage = data->cell_voltage; /* Voltage is in mV */
        }
        break;
    case FUEL_GAUGE_TEMP:
        ret = lc709203f_read_word(dev, LC709203F_REG_CELL_TEMP, &data->cell_temp);
        if (ret == 0) {
            val->temp = data->cell_temp; /* Temperature is in 0.1K */
        }
        break;
    case FUEL_GAUGE_AVG_POWER:
        ret = lc709203f_read_word(dev, LC709203F_REG_APA, &data->apa);
        if (ret == 0) {
            val->avg_power = data->apa;
        }
        break;
    case FUEL_GAUGE_INTERNAL_TEMP:
        ret = lc709203f_read_word(dev, LC709203F_REG_ITE, &data->ite);
        if (ret == 0) {
            val->internal_temp = data->ite;
        }
        break;
    case FUEL_GAUGE_BATTERY_TYPE: /* Not directly supported, return fixed value */
        val->battery_type = FUEL_GAUGE_BATTERY_TYPE_LIPO;
        ret = 0;
        break;
    case FUEL_GAUGE_CYCLE_COUNT: /* Not directly supported, return 0 */
        val->cycle_count = 0;
        ret = 0;
        break;
    case FUEL_GAUGE_STATUS:
        ret = lc709203f_read_word(dev, LC709203F_REG_STATUS, &data->status);
        if (ret == 0) {
            val->status = data->status;
        }
        break;
    case FUEL_GAUGE_ALARM_STATUS:
        ret = lc709203f_read_word(dev, LC709203F_REG_ALARM_WARNING, &data->alarm_warning);
        if (ret == 0) {
            val->alarm_status = data->alarm_warning;
        }
        break;
    default:
        ret = -ENOTSUP;
        break;
    }

    k_mutex_unlock(&data->mutex);

    return ret;
}

static int lc709203f_set_prop(const struct device *dev,
                              enum fuel_gauge_property prop,
                              union fuel_gauge_propval *val)
{
    struct lc709203f_data *data = dev->data;
    int ret;

    k_mutex_lock(&data->mutex, K_FOREVER);

    switch (prop) {
    case FUEL_GAUGE_AVG_POWER:
        ret = lc709203f_write_word(dev, LC709203F_REG_APA, val->avg_power);
        if (ret == 0) {
            data->apa = val->avg_power;
        }
        break;
    case FUEL_GAUGE_INTERNAL_TEMP:
        ret = lc709203f_write_word(dev, LC709203F_REG_ITE, val->internal_temp);
        if (ret == 0) {
            data->ite = val->internal_temp;
        }
        break;
    case FUEL_GAUGE_TEMP_THERMISTOR_B:
        ret = lc709203f_write_word(dev, LC709203F_REG_THERMISTOR_B, val->temp_thermistor_b);
        if (ret == 0) {
            data->thermistor_b = val->temp_thermistor_b;
        }
        break;
    case FUEL_GAUGE_PROFILE:
        ret = lc709203f_write_word(dev, LC709203F_REG_PROFILE, val->profile);
        if (ret == 0) {
            data->profile = val->profile;
        }
        break;
    case FUEL_GAUGE_CC_MODE:
        ret = lc709203f_write_word(dev, LC709203F_REG_CC_MODE, val->cc_mode);
        if (ret == 0) {
            data->cc_mode = val->cc_mode;
        }
        break;
    case FUEL_GAUGE_ALARM_THRESHOLD:
        ret = lc709203f_write_word(dev, LC709203F_REG_ALARM_THRESHOLD, val->alarm_threshold);
        if (ret == 0) {
            data->alarm_threshold = val->alarm_threshold;
        }
        break;
    case FUEL_GAUGE_TEMP_MODE:
        ret = lc709203f_write_word(dev, LC709203F_REG_TEMP_MODE, val->temp_mode);
        if (ret == 0) {
            data->temp_mode = val->temp_mode;
        }
        break;
    case FUEL_GAUGE_VCELL_MODE:
        ret = lc709203f_write_word(dev, LC709203F_REG_VCELL_MODE, val->vcell_mode);
        if (ret == 0) {
            data->vcell_mode = val->vcell_mode;
        }
        break;
    default:
        ret = -ENOTSUP;
        break;
    }

    k_mutex_unlock(&data->mutex);

    return ret;
}

static int lc709203f_init(const struct device *dev)
{
    const struct lc709203f_config *config = dev->config;
    struct lc709203f_data *data = dev->data;
    uint16_t ic_version;
    int ret;

    if (!i2c_is_ready_dt(&config->i2c)) {
        LOG_ERR("I2C bus %s not ready", config->i2c.bus->name);
        return -ENODEV;
    }

    k_mutex_init(&data->mutex);

    ret = lc709203f_read_word(dev, LC709203F_REG_IC_VERSION, &ic_version);
    if (ret < 0) {
        LOG_ERR("Failed to read IC version: %d", ret);
        return ret;
    }

    LOG_INF("Found LC709203F fuel gauge, IC version: 0x%04x", ic_version);

    return 0;
}

#ifdef CONFIG_PM_DEVICE
static int lc709203f_pm_action(const struct device *dev,
                               enum pm_device_action action)
{
    int ret = 0;

    switch (action) {
    case PM_DEVICE_ACTION_RESUME:
    case PM_DEVICE_ACTION_TURN_ON:
        /* Nothing to do to resume/turn on */
        break;
    case PM_DEVICE_ACTION_SUSPEND:
    case PM_DEVICE_ACTION_TURN_OFF:
        /* Nothing to do to suspend/turn off */
        break;
    case PM_DEVICE_ACTION_RELEASE:
        /* Nothing to do to release */
        break;
    default:
        ret = -ENOTSUP;
        break;
    }

    return ret;
}
#endif /* CONFIG_PM_DEVICE */

static const struct fuel_gauge_driver_api lc709203f_driver_api = {
    .get_property = lc709203f_get_prop,
    .set_property = lc709203f_set_prop,
};

#define LC709203F_INIT(inst)                                                   \
    static struct lc709203f_data lc709203f_data_##inst;                        \
    static const struct lc709203f_config lc709203f_config_##inst = {           \
        .i2c = I2C_DT_SPEC_INST_GET(inst),                                     \
    };                                                                         \
    PM_DEVICE_DT_INST_DEFINE(inst, lc709203f_pm_action);                       \
    DEVICE_DT_INST_DEFINE(inst, lc709203f_init, PM_DEVICE_DT_INST_GET(inst),   \
                          &lc709203f_data_##inst,                              \
                          &lc709203f_config_##inst, POST_KERNEL,               \
                          CONFIG_FUEL_GAUGE_LC709203F_INIT_PRIORITY,           \
                          &lc709203f_driver_api);

DT_INST_FOREACH_STATUS_OKAY(LC709203F_INIT)
